package kr.memorynotes;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.text.DateFormat;import java.util.*;
/** Compact document library and per-document study tools. */
public final class PdfLibrary {
 static final int EXPORT=9043,RESTORE=9044;static int sort;
 static void show(final PdfStudy s){if(s.metadataBlocked||s.a.busy)return;if(s.libraryDialog!=null)s.libraryDialog.dismiss();if(s.screen==s.a.root&&!s.remember())return;try{
  final ArrayList<JSONObject> docs=new ArrayList<JSONObject>();for(int i=0;i<s.docs().length();i++)docs.add(s.docs().getJSONObject(i));Collections.sort(docs,new Comparator<JSONObject>(){public int compare(JSONObject x,JSONObject y){if(sort==1)return x.optString("name").compareToIgnoreCase(y.optString("name"));if(sort==2)return Long.compare(size(s,y),size(s,x));return Long.compare(y.optLong("opened"),x.optLong("opened"));}});
  LinearLayout body=s.a.u.col();body.setBackgroundColor(s.a.u.bg);body.setPadding(s.a.u.dp(12),0,s.a.u.dp(12),0);LinearLayout actions=s.row();actions.addView(s.button("＋ PDF 추가",1,new Runnable(){public void run(){importChoice(s);}}));actions.addView(s.button("정렬",0,new Runnable(){public void run(){new AlertDialog.Builder(s.a).setTitle("문서 정렬").setItems(new String[]{"최근 공부순","이름순","원본 용량순"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){sort=i;show(s);}}).show();}}));actions.addView(s.button("전체 백업",0,new Runnable(){public void run(){backupMenu(s);}}));body.addView(actions);
  long used=0;for(JSONObject d:docs)used+=localSize(s,d);body.addView(s.a.u.text("PDF·필기 사용량 "+PdfDocumentRules.size(used)+" · "+docs.size()+"개 문서",12,s.a.u.muted));
  final AlertDialog[] dialog={null};for(final JSONObject d:docs){LinearLayout row=s.row();LinearLayout label=s.a.u.col();TextView name=s.a.u.text(d.optString("name"),15,s.a.u.ink);name.setTypeface(null,Typeface.BOLD);label.addView(name);label.addView(s.a.u.text(info(s,d),11,s.a.u.muted));row.addView(label,new LinearLayout.LayoutParams(0,-2,1));row.setOnClickListener(new View.OnClickListener(){public void onClick(View v){dialog[0].dismiss();s.open(d,-1);}});row.addView(s.button("⋮",0,new Runnable(){public void run(){dialog[0].dismiss();manage(s,d);}}));body.addView(row);}
  if(docs.isEmpty())body.addView(s.a.u.text("PDF를 추가하면 최근 공부한 위치에서 이어 볼 수 있습니다.",14,s.a.u.muted));ScrollView scroll=new ScrollView(s.a);scroll.addView(body);dialog[0]=new AlertDialog.Builder(s.a).setTitle("PDF 문서 관리").setView(scroll).setNegativeButton("닫기",null).create();s.libraryDialog=dialog[0];dialog[0].show();
 }catch(Exception e){s.a.error(e);}}
 static long size(PdfStudy s,JSONObject d){return d.optLong("bytes",new File(s.folder,d.optString("id")+".pdf").length());}
 static long localSize(PdfStudy s,JSONObject d){long bytes=new File(s.folder,d.optString("id")+".pdf").length();File[] files=s.folder.listFiles();if(files!=null)for(File f:files)if(f.getName().startsWith(d.optString("id")+"-")&&f.getName().contains(".ink.json"))bytes+=f.length();return bytes;}
 static String info(PdfStudy s,JSONObject d){String opened=d.optLong("opened")==0?"": " · "+DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT,Locale.KOREA).format(new Date(d.optLong("opened")));return (d.has("uri")?"원본 연결":"앱에 복사")+" · "+PdfDocumentRules.size(size(s,d))+" · 최근 "+(d.optInt("page")+1)+" / "+d.optInt("pages")+"쪽"+opened;}
 static void importChoice(final PdfStudy s){new AlertDialog.Builder(s.a).setTitle("PDF 추가 방식").setItems(new String[]{"앱에 복사 · 원본을 옮겨도 유지","원본 연결 · 중복 저장 없이 사용"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){PdfDocuments.pick(s,i==1,"");}}).show();}
 static void manage(final PdfStudy s,final JSONObject doc){new AlertDialog.Builder(s.a).setTitle(doc.optString("name")).setItems(new String[]{"열기","이름 변경","이 PDF의 암기노트","책갈피","책 쪽수 맞추기","저장 방식 변경 / 원본 다시 연결","PDF 삭제"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){if(i==0)s.open(doc,-1);if(i==1)rename(s,doc);if(i==2)notes(s,doc);if(i==3)bookmarks(s,doc);if(i==4)match(s,doc);if(i==5)storage(s,doc);if(i==6)remove(s,doc);}}).show();}
 static void rename(final PdfStudy s,final JSONObject d){final EditText text=new EditText(s.a);text.setSingleLine(true);text.setText(d.optString("name"));new AlertDialog.Builder(s.a).setTitle("문서 이름 변경").setView(text).setNegativeButton("취소",null).setPositiveButton("변경",new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int n){String value=text.getText().toString().trim();if(value.isEmpty()){s.message("이름을 입력해 주세요.");return;}try{String old=d.optString("name");d.put("name",value);try{s.persist();}catch(Exception e){d.put("name",old);throw e;}if(s.doc==d&&s.screen==s.a.root)s.open(d,s.page);else show(s);}catch(Exception e){s.a.error(e);}}}).show();}
 static void storage(final PdfStudy s,final JSONObject d){if(s.screen==s.a.root&&!s.remember())return;new AlertDialog.Builder(s.a).setTitle("저장 방식 / 원본 연결").setItems(d.has("uri")?new String[]{"앱에 복사로 변경","원본 다시 연결"}:new String[]{"원본 연결로 변경 · 앱 복사본 정리"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int i){if(d.has("uri")&&i==0)PdfDocuments.imported(s,Uri.parse(d.optString("uri")),false,d.optString("id"));else PdfDocuments.pick(s,true,d.optString("id"));}}).show();}
 static void remove(final PdfStudy s,final JSONObject d){new AlertDialog.Builder(s.a).setTitle("PDF 삭제").setMessage(d.optString("name")+"\n\n앱의 PDF 등록과 해당 PDF 위 필기·책갈피를 삭제합니다. 이미 만든 암기노트와 캡처 이미지는 유지됩니다. 패드의 원본 파일은 삭제하지 않습니다.").setNegativeButton("취소",null).setPositiveButton("PDF 삭제",new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int which){try{if(s.a.busy)return;if(s.screen==s.a.root&&!s.remember())return;boolean wasActive=s.doc!=null&&d.getString("id").equals(s.doc.optString("id"))&&s.screen==s.a.root;String activeId=s.doc==null?"":s.doc.optString("id");JSONObject before=new JSONObject(s.state.toString());s.state.put("docs",PdfDocumentRules.without(s.docs(),d.getString("id")));try{s.persist();}catch(Exception e){s.state=before;s.doc=s.doc==null?null:s.findDoc(s.doc.optString("id"));throw e;}
   if(!wasActive&&!activeId.isEmpty())s.doc=s.findDoc(activeId);boolean active=wasActive;if(active){s.ticket++;if(s.search!=null)s.search.dispose();if(s.canvas!=null)s.canvas.dispose();s.screen=null;s.worker.shutdown();s.doc=null;}
   boolean clean=true;File[] files=s.folder.listFiles();String id=d.getString("id");if(files!=null)for(File f:files)if(f.getName().equals(id+".pdf")||(f.getName().startsWith(id+"-")&&f.getName().contains(".ink.json")))if(!f.delete())clean=false;
   if(d.has("uri"))try{boolean shared=false;for(int i=0;i<s.docs().length();i++)if(d.getString("uri").equals(s.docs().getJSONObject(i).optString("uri")))shared=true;if(!shared)s.a.getContentResolver().releasePersistableUriPermission(Uri.parse(d.getString("uri")),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}
   s.message(clean?"PDF 삭제 완료 · 암기노트는 유지됩니다.":"등록은 삭제했습니다. 일부 파일 정리에 실패했습니다.");if(active)s.returner.run();else show(s);
  }catch(Exception e){s.a.error(e);}}}).show();}
 static void match(final PdfStudy s,final JSONObject d){final EditText value=new EditText(s.a);value.setInputType(2);final int page=s.doc==d?s.page:d.optInt("page");value.setText(Integer.toString(Math.max(1,PdfDocumentRules.bookPage(d,page))));new AlertDialog.Builder(s.a).setTitle("책 쪽수 맞추기").setMessage("PDF "+(page+1)+"쪽에 인쇄된 책 쪽수를 입력하세요. 이후 책 쪽수로 바로 이동할 수 있습니다.").setView(value).setNegativeButton("취소",null).setNeutralButton("연결 해제",new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int n){try{Object old=d.opt("bookOffset");d.remove("bookOffset");try{s.persist();}catch(Exception e){if(old!=null)d.put("bookOffset",old);throw e;}if(s.doc==d)s.updatePageLabel();}catch(Exception e){s.a.error(e);}}}).setPositiveButton("설정",new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int n){try{int number=Integer.parseInt(value.getText().toString());if(number<1||number>1000000)throw new IllegalArgumentException();changeOffset(s,d,number-(page+1));}catch(Exception e){s.message("책 쪽수를 1 이상의 숫자로 입력해 주세요.");}}}).show();}
 static void changeOffset(PdfStudy s,JSONObject d,int offset){try{int old=d.optInt("bookOffset");d.put("bookOffset",offset);try{s.persist();}catch(Exception e){d.put("bookOffset",old);throw e;}if(s.doc==d)s.updatePageLabel();s.message("책 쪽수 연결을 변경했습니다.");}catch(Exception e){s.a.error(e);}}
 static void bookmarks(final PdfStudy s,final JSONObject d){try{JSONArray list=PdfDocumentRules.bookmarks(d);final ArrayList<JSONObject> sorted=new ArrayList<JSONObject>();for(int i=0;i<list.length();i++)sorted.add(list.getJSONObject(i));Collections.sort(sorted,new Comparator<JSONObject>(){public int compare(JSONObject x,JSONObject y){return Integer.compare(x.optInt("page"),y.optInt("page"));}});String[] labels=new String[sorted.size()+1];labels[0]="＋ 현재 페이지 책갈피";for(int i=0;i<sorted.size();i++){JSONObject b=sorted.get(i);labels[i+1]=b.optString("category")+" · "+b.optString("title")+" · PDF "+(b.optInt("page")+1)+"쪽";}
  new AlertDialog.Builder(s.a).setTitle("책갈피 · "+d.optString("name")).setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int which){if(which==0){bookmarkEdit(s,d,s.doc==d?s.page:d.optInt("page"));return;}final JSONObject b=sorted.get(which-1);new AlertDialog.Builder(s.a).setTitle(b.optString("title")).setItems(new String[]{"이동","이름·분류 수정","책갈피 삭제"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface z,int n){if(n==0)s.open(d,b.optInt("page"));if(n==1)bookmarkEdit(s,d,b.optInt("page"));if(n==2)try{JSONArray old=new JSONArray(d.getJSONArray("bookmarks").toString());JSONArray next=new JSONArray();for(int j=0;j<old.length();j++)if(old.getJSONObject(j).optInt("page")!=b.optInt("page"))next.put(old.getJSONObject(j));d.put("bookmarks",next);try{s.persist();}catch(Exception e){d.put("bookmarks",old);throw e;}bookmarks(s,d);}catch(Exception e){s.a.error(e);}}}).show();}}).show();
 }catch(Exception e){s.a.error(e);}}
 static void bookmarkEdit(final PdfStudy s,final JSONObject d,final int page){try{LinearLayout body=s.a.u.col();final EditText title=new EditText(s.a);title.setHint("책갈피 이름");title.setText("PDF "+(page+1)+"쪽");body.addView(title);final Spinner category=new Spinner(s.a);String[] cats={"중요","공식","다시 풀기","헷갈림"};category.setAdapter(new ArrayAdapter<String>(s.a,android.R.layout.simple_spinner_dropdown_item,cats));body.addView(category);JSONArray list=PdfDocumentRules.bookmarks(d);for(int i=0;i<list.length();i++){JSONObject b=list.getJSONObject(i);if(b.optInt("page")==page){title.setText(b.optString("title"));for(int j=0;j<cats.length;j++)if(cats[j].equals(b.optString("category")))category.setSelection(j);}}
  new AlertDialog.Builder(s.a).setTitle("책갈피 저장").setView(body).setNegativeButton("취소",null).setPositiveButton("저장",new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int n){try{JSONArray old=new JSONArray(PdfDocumentRules.bookmarks(d).toString());String name=title.getText().toString().trim();PdfDocumentRules.bookmark(d,page,name.isEmpty()?"PDF "+(page+1)+"쪽":name,category.getSelectedItem().toString());try{s.persist();}catch(Exception e){d.put("bookmarks",old);throw e;}s.message("책갈피 저장 완료");}catch(Exception e){s.a.error(e);}}}).show();
 }catch(Exception e){s.a.error(e);}}
 static void notes(final PdfStudy s,final JSONObject d){final ArrayList<Note> found=new ArrayList<Note>();ArrayList<String> titles=new ArrayList<String>();for(Note n:s.a.db.query(""))if(PdfDocumentRules.uses(s.notes().optJSONObject(n.id),d.optString("id"))){found.add(n);titles.add(n.title);}if(found.isEmpty()){s.message("이 PDF에서 만든 암기노트가 없습니다.");return;}String[] labels=new String[titles.size()+1];labels[0]="▶ 이 PDF의 노트 전체 복습 · "+found.size()+"개";for(int i=0;i<titles.size();i++)labels[i+1]=titles.get(i);new AlertDialog.Builder(s.a).setTitle("이 PDF의 암기노트").setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int n){if(s.screen==s.a.root&&!s.remember())return;s.ticket++;if(s.search!=null)s.search.dispose();if(s.canvas!=null)s.canvas.dispose();s.screen=null;s.worker.shutdown();if(n==0)s.a.beginReview(found);else s.a.detail(found.get(n-1));}}).show();}
 static void backupMenu(final PdfStudy s){new AlertDialog.Builder(s.a).setTitle("전체 백업 · PDF·필기·암기노트").setItems(new String[]{"전체 백업 저장","전체 백업 복원"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){if(s.screen==s.a.root&&!s.remember())return;if(i==0)s.a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"MemoryNote-full-"+System.currentTimeMillis()+".zip"),EXPORT);else new AlertDialog.Builder(s.a).setTitle("전체 백업 복원").setMessage("현재 노트와 PDF 학습기록을 백업 내용으로 교체합니다. 먼저 현재 전체 백업을 저장하는 것을 권합니다.").setNegativeButton("취소",null).setPositiveButton("백업 선택",new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int n){s.a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE),RESTORE);}}).show();}}).show();}
 static boolean result(final MainActivity a,int req,int result,Intent data){if(req!=EXPORT&&req!=RESTORE)return false;if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return true;if(a.busy)return true;final boolean restore=req==RESTORE;final Uri uri=data.getData();final PdfStudy s=PdfStudy.sessions.get(a);if(s!=null&&s.screen==a.root&&!s.remember())return true;if(s!=null){s.ticket++;if(s.search!=null)s.search.cancel();}a.startBusy(restore?"전체 백업을 검사하고 복원하는 중…":"PDF·필기·노트를 백업하는 중…");new Thread(new Runnable(){public void run(){Exception error=null;try{if(restore)try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("백업을 열 수 없습니다.");PdfFullBackup.restoreFrom(a,in);}else try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("백업을 저장할 수 없습니다.");PdfFullBackup.exportTo(a,out);}}catch(Exception e){error=e;}final Exception failure=error;a.runOnUiThread(new Runnable(){public void run(){a.endBusy();if(failure!=null){if(s!=null&&s.screen==a.root)s.render();a.error(failure);return;}if(restore){if(s!=null){s.destroyed=true;if(s.search!=null)s.search.dispose();if(s.canvas!=null)s.canvas.dispose();s.screen=null;s.worker.shutdownNow();PdfStudy.sessions.remove(a);}a.editor=null;a.getPreferences(0).edit().remove("draft").remove("saved_draft_archive").apply();a.show("홈");}if(!restore&&s!=null&&s.screen==a.root)s.render();a.u.message(restore?"PDF·필기·암기노트 전체 복원 완료":"PDF·필기·암기노트 전체 백업 완료");}});}}).start();return true;}
}
